class Solution {
public:
    int numberOfWays(int numPeople) {
        long long MOD = 1e9 + 7;
        int n = numPeople / 2;
        std::vector<long long> dp(n + 1, 0);
        dp[0] = 1;
        for (int i = 1; i <= n; ++i) {
            for (int j = 0; j < i; ++j) {
                dp[i] = (dp[i] + dp[j] * dp[i - 1 - j]) % MOD;
            }
        }
        return dp[n];
    }
};

class Solution {
    public int numberOfWays(int numPeople) {
        long MOD = 1_000_000_007L;
        int n = numPeople / 2;
        long[] dp = new long[n + 1];
        dp[0] = 1;
        for (int i = 1; i <= n; i++) {
            for (int j = 0; j < i; j++) {
                dp[i] = (dp[i] + dp[j] * dp[i - 1 - j]) % MOD;
            }
        }
        return (int) dp[n];
    }
}

var numberOfWays = function(numPeople) {
    const MOD = 1000000007n;
    const n = Math.floor(numPeople / 2);
    const dp = new Array(n + 1).fill(0n);
    dp[0] = 1n;
    for (let i = 1; i <= n; i++) {
        for (let j = 0; j < i; j++) {
            dp[i] = (dp[i] + dp[j] * dp[i - 1 - j]) % MOD;
        }
    }
    return Number(dp[n]);
};
